            _ = vg.copy(runeRange, rr, tmp);
        }
    }
}

pub fn finalizeBracket(mem: vg.Allocator, b: *bracketSet, loc: *Locale) vg.Allocator.Error!void {
    if (((!b.negated) and ((b.elems.len > 0) or (b.equivs.len > 0)))) {
        {
            var i: i64 = 0;
            while ((i < b.elems.len)) : (i +%= 1) {
                b.multiLens |= (@as(u16, 1) << @intCast(b.elems.at(i).*.len));
            }
        }
        if ((b.equivs.len > 0)) {
            {
                var length: i64 = 2;
                while ((length <= localeMaxElementLength(loc))) : (length +%= 1) {
                    b.multiLens |= (@as(u16, 1) << @intCast(length));
                }
            }
        }
    }
    if ((b.ranges.len < 2)) {
        return;
    }
    try sortRanges(mem, b.ranges);
    var w: i64 = 0;
    {
        var i_2: i64 = 1;
        while ((i_2 < b.ranges.len)) : (i_2 +%= 1) {
            if ((b.ranges.at(i_2).*.lo <= (b.ranges.at(w).*.hi +% 1))) {
                if ((b.ranges.at(i_2).*.hi > b.ranges.at(w).*.hi)) {
                    b.ranges.at(w).*.hi = b.ranges.at(i_2).*.hi;
                }
            } else {
                w +%= 1;
                b.ranges.at(w).* = b.ranges.at(i_2).*;
            }
        }
    }
    b.ranges = b.ranges.head((w +% 1));
}

pub fn bracketInRanges(brs: vg.Slice(bracketSet), bi: i32, c: i32) bool {
    var low: i64 = 0;
    var high: i64 = brs.at(bi).*.ranges.len;
    while ((low < high)) {
        const middle: i64 = (low +% vg.divT((high -% low), 2));
        if ((brs.at(bi).*.ranges.at(middle).*.hi < c)) {
            low = (middle +% 1);
        } else {
            if ((brs.at(bi).*.ranges.at(middle).*.lo > c)) {
                high = middle;
            } else {
                return true;
            }
        }
    }
    return false;
}

pub fn bracketPositiveSingle(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, c: i32) bool {
    if (bracketInRanges(brs, bi, c)) {
        return true;
    }
    if (((brs.at(bi).*.classMask != 0) and ((localeClassMask(loc, c) & brs.at(bi).*.classMask) != 0))) {
        return true;
    }
    var single: [1]i32 = @splat(0);
    single[0] = c;
    {
        var i: i64 = 0;
        while ((i < brs.at(bi).*.equivs.len)) : (i +%= 1) {
            if (localePrimaryEqual(loc, vg.arrSlice(i32, &single, 0, 1), brs.at(bi).*.equivs.at(i).*)) {
                return true;
            }
        }
    }
    return false;
}

pub fn bracketMatchesOne(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, c: i32) bool {
    if ((c < 0)) {
        return false;
    }
    if (((brs.at(bi).*.negated and brs.at(bi).*.nlMode) and (c == 10))) {
        return false;
    }
    const want: bool = (!brs.at(bi).*.negated);
    if ((bracketPositiveSingle(brs, bi, loc, c) == want)) {
        return true;
    }
    if ((!brs.at(bi).*.icase)) {
        return false;
    }
    var buf: preimageBuf = .{};
    localeCasePreimages(loc, &buf, c);
    {
        var i: i64 = 0;
        while ((i < buf.n)) : (i +%= 1) {
            if ((bracketPositiveSingle(brs, bi, loc, buf.r[@intCast(i)]) == want)) {
                return true;
            }
        }
    }
    return false;
}

pub fn counterpartMatch(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, t: i32, e: i32) bool {
    if ((t == e)) {
        return true;
    }
    if ((!brs.at(bi).*.icase)) {
        return false;
    }
    return ((t == localeToUpper(loc, e)) or (t == localeToLower(loc, e)));
}

pub fn bracketHasMultiMembers(brs: vg.Slice(bracketSet), bi: i32) bool {
    return ((!brs.at(bi).*.negated) and ((brs.at(bi).*.elems.len > 0) or (brs.at(bi).*.equivs.len > 0)));
}

pub fn bracketMatchesMulti(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, t: vg.Slice(i32)) bool {
    if ((t.len > localeMaxElementLength(loc))) {
        return false;
    }
    {
        var i: i64 = 0;
        while ((i < brs.at(bi).*.elems.len)) : (i +%= 1) {
            if ((brs.at(bi).*.elems.at(i).*.len != t.len)) {
                continue;
            }
            var all: bool = true;
            {
                var k: i64 = 0;
                while ((k < t.len)) : (k +%= 1) {
                    if ((!counterpartMatch(brs, bi, loc, t.at(k).*, brs.at(bi).*.elems.at(i).*.at(k).*))) {
                        all = false;
                        break;
                    }
                }
            }
            if (all) {
                return true;
            }
        }
    }
    if ((brs.at(bi).*.equivs.len == 0)) {
        return false;
    }
    var candidate: elemBuf = .{};
    return equivCandidate(brs, bi, loc, t, &candidate, 0);
}

pub fn equivCandidate(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, t: vg.Slice(i32), candidate: *elemBuf, at: i64) bool {
    if ((at == t.len)) {
        if ((!localeIsCollatingElement(loc, vg.arrSlice(i32, &candidate.r, 0, t.len)))) {
            return false;
        }
        {
            var i: i64 = 0;
            while ((i < brs.at(bi).*.equivs.len)) : (i +%= 1) {
                if (localePrimaryEqual(loc, vg.arrSlice(i32, &candidate.r, 0, t.len), brs.at(bi).*.equivs.at(i).*)) {
                    return true;
                }
            }
        }
        return false;
    }
    candidate.r[@intCast(at)] = t.at(at).*;
    if (equivCandidate(brs, bi, loc, t, candidate, (at +% 1))) {
        return true;
    }
    if ((!brs.at(bi).*.icase)) {
        return false;
    }
    var buf: preimageBuf = .{};
    localeCasePreimages(loc, &buf, t.at(at).*);
    {
        var i_2: i64 = 0;
        while ((i_2 < buf.n)) : (i_2 +%= 1) {
            candidate.r[@intCast(at)] = buf.r[@intCast(i_2)];
            if (equivCandidate(brs, bi, loc, t, candidate, (at +% 1))) {
                return true;
            }
        }
    }
    return false;
}

pub fn bracketMatchesSpan(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale, runes: vg.Slice(i32), i: i64, j: i64) bool {
    const k: i64 = (j -% i);
    if ((k < 1)) {
        return false;
    }
    if ((k == 1)) {
        return bracketMatchesOne(brs, bi, loc, runes.at(i).*);
    }
    if ((!bracketHasMultiMembers(brs, bi))) {
        return false;
    }
    return bracketMatchesMulti(brs, bi, loc, runes.sub(i, j));
}

pub fn bracketMinChars(brs: vg.Slice(bracketSet), bi: i32, loc: *Locale) i64 {
    if ((((brs.at(bi).*.negated or (brs.at(bi).*.ranges.len > 0)) or (brs.at(bi).*.classMask != 0)) or ((brs.at(bi).*.elems.len == 0) and (brs.at(bi).*.equivs.len == 0)))) {
        return 1;
    }
    var best: i64 = lenInf;
    {
        var i: i64 = 0;
        while ((i < brs.at(bi).*.elems.len)) : (i +%= 1) {
            best = @min(best, brs.at(bi).*.elems.at(i).*.len);
        }
    }
    {
        var i_2: i64 = 0;
        while ((i_2 < brs.at(bi).*.equivs.len)) : (i_2 +%= 1) {
            best = @min(best, localeMinEquivLength(loc, brs.at(bi).*.equivs.at(i_2).*));
        }
    }
    return best;
}

pub fn capStep(s: *capSolver) bool {
    s.work +%= 1;
    if ((s.work > capWorkLimit)) {
        s.failed = true;
    }
    return (!s.failed);
}

pub fn seedArenas(mem: vg.Allocator, s: *capSolver) vg.Allocator.Error!void {
    const scratch: ptree = .{};
    s.trees = try vg.append(mem, ptree, s.trees, scratch);
    s.kidStore = try vg.append(mem, i32, s.kidStore, (-%1));
}

pub fn newTree(mem: vg.Allocator, s: *capSolver, t: ptree) vg.Allocator.Error!i32 {
    if ((s.failed or (s.trees.len >= solverArenaLimit))) {
        s.failed = true;
        s.trees.at(0).* = t;
        return 0;
    }
    s.trees = try vg.append(mem, ptree, s.trees, t);
    return vg.cv(i32, (s.trees.len -% 1));
}

pub fn kidAlloc(mem: vg.Allocator, s: *capSolver, length: i64) vg.Allocator.Error!i64 {
    if ((s.failed or ((s.kidStore.len +% length) > solverArenaLimit))) {
        s.failed = true;
        while ((s.kidStore.len < length)) {
            s.kidStore = try vg.append(mem, i32, s.kidStore, (-%1));
        }
        return 0;
    }
    const off: i64 = s.kidStore.len;
    if (((off +% length) <= s.kidStore.cap)) {
        s.kidStore = s.kidStore.head((off +% length));
        return off;
    }
    {
        var i: i64 = 0;
        while ((i < length)) : (i +%= 1) {
            s.kidStore = try vg.append(mem, i32, s.kidStore, (-%1));
        }
    }
    return off;
}

pub fn kidAlloc1(mem: vg.Allocator, s: *capSolver, t: i32) vg.Allocator.Error!i64 {
    const off: i64 = try kidAlloc(mem, s, 1);
    s.kidStore.at(off).* = t;
    return off;
}

pub fn kidPrepend(mem: vg.Allocator, s: *capSolver, head: i32, tailOff: i64, tailLen: i64) vg.Allocator.Error!i64 {
    const off: i64 = try kidAlloc(mem, s, (tailLen +% 1));
    s.kidStore.at(off).* = head;
    _ = vg.copy(i32, s.kidStore.sub((off +% 1), ((off +% 1) +% tailLen)), s.kidStore.sub(tailOff, (tailOff +% tailLen)));
    return off;
}

pub fn setMatch(caps: vg.Slice(Match), idx: i64, so: i64, eo: i64) void {
    caps.at(idx).*.So = so;
    caps.at(idx).*.Eo = eo;
}

pub fn addCounters(s: *capSolver, re: *Regexp, t: i32, out: vg.Slice(i64)) void {
    const ni: i32 = s.trees.at(t).*.n;
    if (((re.nodes.at(ni).*.op == opRepeat) and re.nodes.at(ni).*.minimal)) {
        out.at(re.nodes.at(ni).*.index).* +%= vg.cv(i64, (s.trees.at(t).*.j -% s.trees.at(t).*.i));
    }
    const off: i64 = vg.cv(i64, s.trees.at(t).*.kidsOff);
    const count: i64 = vg.cv(i64, s.trees.at(t).*.kidsLen);
    {
        var k: i64 = 0;
        while ((k < count)) : (k +%= 1) {
            addCounters(s, re, s.kidStore.at((off +% k)).*, out);
        }
    }
}

pub fn structCmp(s: *capSolver, re: *Regexp, a: i32, b: i32) i64 {
    const spanA: i64 = vg.cv(i64, (s.trees.at(a).*.j -% s.trees.at(a).*.i));
    const spanB: i64 = vg.cv(i64, (s.trees.at(b).*.j -% s.trees.at(b).*.i));
    const ni: i32 = s.trees.at(a).*.n;
    if ((spanA != spanB)) {
        if (((re.nodes.at(ni).*.op == opRepeat) and re.nodes.at(ni).*.minimal)) {
            return (spanA -% spanB);
        }
        return (spanB -% spanA);
    }
    const offA: i64 = vg.cv(i64, s.trees.at(a).*.kidsOff);
    const offB: i64 = vg.cv(i64, s.trees.at(b).*.kidsOff);
    const lenA: i64 = vg.cv(i64, s.trees.at(a).*.kidsLen);
    const lenB: i64 = vg.cv(i64, s.trees.at(b).*.kidsLen);
    switch (re.nodes.at(ni).*.op) {
        opAlt => {
            if ((s.trees.at(a).*.branch != s.trees.at(b).*.branch)) {
                return vg.cv(i64, (s.trees.at(a).*.branch -% s.trees.at(b).*.branch));
            }
            return structCmp(s, re, s.kidStore.at(offA).*, s.kidStore.at(offB).*);
        },
        opConcat, opGroup => {
            {
                var idx: i64 = 0;
                while ((idx < lenA)) : (idx +%= 1) {
                    const c: i64 = structCmp(s, re, s.kidStore.at((offA +% idx)).*, s.kidStore.at((offB +% idx)).*);
                    if ((c != 0)) {
                        return c;
                    }
                }
            }
        },
        opRepeat => {
            const limit: i64 = @min(lenA, lenB);
            {
                var idx_2: i64 = 0;
                while ((idx_2 < limit)) : (idx_2 +%= 1) {
                    const ka: i32 = s.kidStore.at((offA +% idx_2)).*;
                    const kb: i32 = s.kidStore.at((offB +% idx_2)).*;
                    const sa: i64 = vg.cv(i64, (s.trees.at(ka).*.j -% s.trees.at(ka).*.i));
                    const sb: i64 = vg.cv(i64, (s.trees.at(kb).*.j -% s.trees.at(kb).*.i));
                    if ((sa != sb)) {
                        if (re.nodes.at(ni).*.minimal) {
                            return (sa -% sb);
                        }
                        return (sb -% sa);
                    }
                }
            }
            if ((lenA != lenB)) {
                return (lenA -% lenB);
            }
            {
                var idx_3: i64 = 0;
                while ((idx_3 < lenA)) : (idx_3 +%= 1) {
                    const c_2: i64 = structCmp(s, re, s.kidStore.at((offA +% idx_3)).*, s.kidStore.at((offB +% idx_3)).*);
                    if ((c_2 != 0)) {
                        return c_2;
                    }
                }
            }
        },
        else => {},
    }
    return 0;
}

pub fn cmpCand(s: *capSolver, re: *Regexp, a: i32, b: i32) i64 {
    if (s.failed) {
        return 1;
    }
    if ((re.minSlots > 0)) {
        {
            var idx: i64 = 0;
            while ((idx < re.minSlots)) : (idx +%= 1) {
                s.ctrA.at(idx).* = 0;
                s.ctrB.at(idx).* = 0;
            }
        }
        addCounters(s, re, a, s.ctrA);
        addCounters(s, re, b, s.ctrB);
        {
            var idx_2: i64 = 0;
            while ((idx_2 < re.minSlots)) : (idx_2 +%= 1) {
                if ((s.ctrA.at(idx_2).* != s.ctrB.at(idx_2).*)) {
                    return (s.ctrA.at(idx_2).* -% s.ctrB.at(idx_2).*);
                }
            }
        }
    }
    return structCmp(s, re, a, b);
}

pub fn bestParse(mem: vg.Allocator, s: *capSolver, re: *Regexp, d: *decoded, ni: i32, i: i64, j: i64) vg.Allocator.Error!i32 {
    const span: i64 = (j -% i);
    if (((span < re.nodes.at(ni).*.minL) or ((re.nodes.at(ni).*.maxL < lenInf) and (span > re.nodes.at(ni).*.maxL)))) {
        return (-%1);
    }
    var key: memoKey = .{};
    key.a = ni;
    key.b = vg.cv(i32, i);
    key.c = vg.cv(i32, j);
    const _t1 = memoGet(&s.memo, key);
    const cached: memoVal = _t1[0];
    const hit: bool = _t1[1];
    if (hit) {
        return cached.x;
    }
    if ((!capStep(s))) {
        return (-%1);
    }
    var best: i32 = vg.cv(i32, (-%1));
    switch (re.nodes.at(ni).*.op) {
        opChar => {
            if (((j == (i +% 1)) and charMatches(re, ni, d.runes.at(i).*))) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
            }
        },
        opAny => {
            if (((j == (i +% 1)) and anyMatches(re, d.runes.at(i).*))) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
            }
        },
        opBracket => {
            if (bracketMatchesSpan(re.brackets, re.nodes.at(ni).*.br, &re.loc, d.runes, i, j)) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
            }
        },
        opBOL => {
            if (((j == i) and atBOL(re, d, i, s.eflags))) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
            }
        },
        opEOL => {
            if (((j == i) and atEOL(re, d, i, s.eflags))) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
            }
        },
        opGroup => {
            const sub: i32 = try bestParse(mem, s, re, d, re.nodes.at(ni).*.ch.at(0).*, i, j);
            if ((sub >= 0)) {
                const off: i64 = try kidAlloc1(mem, s, sub);
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, off), .kidsLen = 1 });
            }
        },
        opAlt => {
            {
                var bi: i64 = 0;
                while ((bi < re.nodes.at(ni).*.ch.len)) : (bi +%= 1) {
                    const sub_2: i32 = try bestParse(mem, s, re, d, re.nodes.at(ni).*.ch.at(bi).*, i, j);
                    if ((sub_2 < 0)) {
                        continue;
                    }
                    const off_2: i64 = try kidAlloc1(mem, s, sub_2);
                    const candidate: i32 = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .branch = vg.cv(i32, bi), .kidsOff = vg.cv(i32, off_2), .kidsLen = 1 });
                    if (((best < 0) or (cmpCand(s, re, candidate, best) < 0))) {
                        best = candidate;
                    }
                }
            }
        },
        opConcat => {
            const _t2 = try bestConcat(mem, s, re, d, ni, 0, i, j);
            const off_3: i64 = _t2[0];
            const count: i64 = _t2[1];
            if ((off_3 >= 0)) {
                best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, off_3), .kidsLen = vg.cv(i32, count) });
            }
        },
        opRepeat => {
            if (((i == j) and (re.nodes.at(ni).*.min == 0))) {
                var sub_3: i32 = vg.cv(i32, (-%1));
                if ((re.nodes.at(ni).*.max != 0)) {
                    sub_3 = try bestParse(mem, s, re, d, re.nodes.at(ni).*.ch.at(0).*, i, i);
                }
                if ((sub_3 >= 0)) {
                    const off_4: i64 = try kidAlloc1(mem, s, sub_3);
                    best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, off_4), .kidsLen = 1 });
                } else {
                    best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j) });
                }
            } else {
                const win: repWin = try bestRep(mem, s, re, d, ni, i, j, 0, false);
                if (win.ok) {
                    best = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, win.off), .kidsLen = vg.cv(i32, win.length) });
                }
            }
        },
        else => {},
    }
    var val: memoVal = .{};
    val.x = best;
    try memoPut(mem, &s.memo, key, val);
    return best;
}

pub fn bestConcat(mem: vg.Allocator, s: *capSolver, re: *Regexp, d: *decoded, ni: i32, idx: i64, i: i64, j: i64) vg.Allocator.Error!Tup_i64_i64 {
    if ((idx == (re.nodes.at(ni).*.ch.len -% 1))) {
        const sub: i32 = try bestParse(mem, s, re, d, re.nodes.at(ni).*.ch.at(idx).*, i, j);
        if ((sub < 0)) {
            return .{ (-%1), 0 };
        }
        return .{ try kidAlloc1(mem, s, sub), 1 };
    }
    var key: memoKey = .{};
    key.a = ni;
    key.b = vg.cv(i32, idx);
    key.c = vg.cv(i32, i);
    key.d = vg.cv(i32, j);
    const _t1 = memoGet(&s.cmemo, key);
    const cached: memoVal = _t1[0];
    const hit: bool = _t1[1];
    if (hit) {
        return .{ vg.cv(i64, cached.x), vg.cv(i64, cached.y) };
    }
    if ((!capStep(s))) {
        return .{ (-%1), 0 };
    }
    var bestOff: i64 = (-%1);
    var bestLen: i64 = 0;
    var bestTree: i32 = vg.cv(i32, (-%1));
    const head0: i32 = re.nodes.at(ni).*.ch.at(idx).*;
    var lo: i64 = (i +% re.nodes.at(head0).*.minL);
    if ((re.nodes.at(ni).*.sufMax.at((idx +% 1)).* < lenInf)) {
        lo = @max(lo, (j -% re.nodes.at(ni).*.sufMax.at((idx +% 1)).*));
    }
    var hi: i64 = (j -% re.nodes.at(ni).*.sufMin.at((idx +% 1)).*);
    if ((re.nodes.at(head0).*.maxL < lenInf)) {
        hi = @min(hi, (i +% re.nodes.at(head0).*.maxL));
    }
    {
        var m: i64 = lo;
        while ((m <= hi)) : (m +%= 1) {
            if ((!capStep(s))) {
                return .{ (-%1), 0 };
            }
            const head: i32 = try bestParse(mem, s, re, d, head0, i, m);
            if ((head < 0)) {
                continue;
            }
            const _t2 = try bestConcat(mem, s, re, d, ni, (idx +% 1), m, j);
            const tailOff: i64 = _t2[0];
            const tailLen: i64 = _t2[1];
            if ((tailOff < 0)) {
                continue;
            }
            const off: i64 = try kidPrepend(mem, s, head, tailOff, tailLen);
            const candidate: i32 = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, off), .kidsLen = vg.cv(i32, (tailLen +% 1)) });
            if (((bestTree < 0) or (cmpCand(s, re, candidate, bestTree) < 0))) {
                bestTree = candidate;
                bestOff = off;
                bestLen = (tailLen +% 1);
            }
        }
    }
    var val: memoVal = .{};
    val.x = vg.cv(i32, bestOff);
    val.y = vg.cv(i32, bestLen);
    try memoPut(mem, &s.cmemo, key, val);
    return .{ bestOff, bestLen };
}

pub fn repTry(mem: vg.Allocator, s: *capSolver, re: *Regexp, ni: i32, i: i64, j: i64, off: i64, length: i64, best: *repBest) vg.Allocator.Error!void {
    const candidate: i32 = try newTree(mem, s, ptree{ .n = ni, .i = vg.cv(i32, i), .j = vg.cv(i32, j), .kidsOff = vg.cv(i32, off), .kidsLen = vg.cv(i32, length) });
    if (((!best.found) or (cmpCand(s, re, candidate, best.tree) < 0))) {
        best.off = off;
        best.length = length;
        best.tree = candidate;
        best.found = true;
    }
}

pub fn bestRep(mem: vg.Allocator, s: *capSolver, re: *Regexp, d: *decoded, ni: i32, i: i64, j: i64, done: i64, hasEmpty: bool) vg.Allocator.Error!repWin {
    var done_v: i64 = done;
    if (((re.nodes.at(ni).*.max == infinite) and (done_v > re.nodes.at(ni).*.min))) {
        done_v = re.nodes.at(ni).*.min;
    }
    var key: memoKey = .{};
    key.a = ni;
    key.b = vg.cv(i32, i);
    key.c = vg.cv(i32, j);
    key.d = vg.cv(i32, (done_v << 1));
    if (hasEmpty) {
        key.d |= 1;
    }
    var win: repWin = .{};
    const _t1 = memoGet(&s.rmemo, key);
    const cached: memoVal = _t1[0];
    const hit: bool = _t1[1];
    if (hit) {
        win.off = vg.cv(i64, cached.x);
        win.length = vg.cv(i64, cached.y);
        win.ok = (cached.z != 0);
        return win;
    }
    if ((!capStep(s))) {
        win.off = (-%1);
        return win;
    }
    var best: repBest = .{};
    if ((((i == j) and (done_v >= re.nodes.at(ni).*.min)) and ((!hasEmpty) or (done_v == re.nodes.at(ni).*.min)))) {
        try repTry(mem, s, re, ni, i, j, 0, 0, &best);
    }
    const canTake: bool = ((re.nodes.at(ni).*.max == infinite) or (done_v < re.nodes.at(ni).*.max));
    if ((canTake and (!(hasEmpty and (done_v >= re.nodes.at(ni).*.min))))) {
        const child: i32 = re.nodes.at(ni).*.ch.at(0).*;
        const tailMin: i64 = satMul(@max(((re.nodes.at(ni).*.min -% done_v) -% 1), 0), re.nodes.at(child).*.minL);
        var tailMax: i64 = lenInf;
        if ((re.nodes.at(ni).*.max != infinite)) {
            tailMax = satMul(((re.nodes.at(ni).*.max -% done_v) -% 1), re.nodes.at(child).*.maxL);
        } else {
            if ((re.nodes.at(child).*.maxL == 0)) {
                tailMax = 0;
            }
        }
        var lo: i64 = (i +% re.nodes.at(child).*.minL);
        if ((tailMax < lenInf)) {
            lo = @max(lo, (j -% tailMax));
        }
        var hi: i64 = (j -% tailMin);
        if ((re.nodes.at(child).*.maxL < lenInf)) {
            hi = @min(hi, (i +% re.nodes.at(child).*.maxL));
        }
        {
            var m: i64 = lo;
            while ((m <= hi)) : (m +%= 1) {
                if (((m == i) and (done_v >= re.nodes.at(ni).*.min))) {
                    continue;
                }
                if ((!capStep(s))) {
                    win.off = (-%1);
                    return win;
                }
                const head: i32 = try bestParse(mem, s, re, d, child, i, m);
                if ((head < 0)) {
                    continue;
                }
                const tail: repWin = try bestRep(mem, s, re, d, ni, m, j, (done_v +% 1), (hasEmpty or (m == i)));
                if ((!tail.ok)) {
                    continue;
                }
                const off: i64 = try kidPrepend(mem, s, head, tail.off, tail.length);
                try repTry(mem, s, re, ni, i, j, off, (tail.length +% 1), &best);
            }
        }
    }
    var val: memoVal = .{};
    val.x = vg.cv(i32, best.off);
    val.y = vg.cv(i32, best.length);
    if (best.found) {
        val.z = 1;
    } else {
        val.x = (-%1);
    }
    try memoPut(mem, &s.rmemo, key, val);
    win.off = vg.cv(i64, val.x);
    win.length = vg.cv(i64, val.y);
    win.ok = best.found;
    return win;
}

pub fn solveCaptures(mem: vg.Allocator, re: *Regexp, d: *decoded, so: i64, eo: i64, eflags: u32, caps: vg.Slice(Match)) vg.Allocator.Error!Error {
    if (re.onePass) {
        {
            var idx: i64 = 0;
            while ((idx < caps.len)) : (idx +%= 1) {
                setMatch(caps, idx, (-%1), (-%1));
            }
        }
        setMatch(caps, 0, so, eo);
        if (onePassCaps(re, d, re.root, so, eo, eflags, caps)) {
            return noError();
        }
    }
    var s: capSolver = .{};
    s.eflags = eflags;
    s.ctrA = try vg.make(mem, i64, re.minSlots);
    s.ctrB = try vg.make(mem, i64, re.minSlots);
    try seedArenas(mem, &s);
    const best: i32 = try bestParse(mem, &s, re, d, re.root, so, eo);
    if (s.failed) {
        return compileError(ErrESpace, (-%1));
    }
    if ((best < 0)) {
        return compileError(ErrESpace, (-%1));
    }
    {
        var idx_2: i64 = 0;
        while ((idx_2 < caps.len)) : (idx_2 +%= 1) {
            setMatch(caps, idx_2, (-%1), (-%1));
        }
    }
    setMatch(caps, 0, so, eo);
    assignCaps(re, &s, best, caps);
    return noError();
}

pub fn assignCaps(re: *Regexp, s: *capSolver, t: i32, caps: vg.Slice(Match)) void {
    const ni: i32 = s.trees.at(t).*.n;
    if ((re.nodes.at(ni).*.op == opGroup)) {
        const gi: i64 = re.nodes.at(ni).*.index;
        {
            var k: i64 = 0;
            while ((k < re.nested.at(gi).*.len)) : (k +%= 1) {
                setMatch(caps, vg.cv(i64, re.nested.at(gi).*.at(k).*), (-%1), (-%1));
            }
        }
        setMatch(caps, gi, vg.cv(i64, s.trees.at(t).*.i), vg.cv(i64, s.trees.at(t).*.j));
    }
    const off: i64 = vg.cv(i64, s.trees.at(t).*.kidsOff);
    const count: i64 = vg.cv(i64, s.trees.at(t).*.kidsLen);
    {
        var k_2: i64 = 0;
        while ((k_2 < count)) : (k_2 +%= 1) {
            assignCaps(re, s, s.kidStore.at((off +% k_2)).*, caps);
        }
    }
}

pub fn cAdd(a: i64, b: i64) i64 {
    if ((a > (contractCap -% b))) {
        return contractCap;
    }
    return (a +% b);
}

pub fn cMul(a: i64, b: i64) i64 {
    if (((a == 0) or (b == 0))) {
        return 0;
    }
    if ((a > vg.divT(@as(i64, contractCap), b))) {
        return contractCap;
    }
    return (a *% b);
}

pub fn ContractHeapBytes(c: *Contract) i64 {
    var capture: i64 = vg.cv(i64, 0);
    if (c.HasOnePass) {
        capture = c.OnePass.HeapBytes;
    }
    if (c.HasSolver) {
        capture = @max(capture, c.Solver.HeapBytes);
    }
    return cAdd(c.Matcher.HeapBytes, capture);
}

pub fn ContractStackBytes(c: *Contract) i64 {
    var deepest: i64 = c.Matcher.StackBytes;
    if (c.HasOnePass) {
        deepest = @max(deepest, c.OnePass.StackBytes);
    }
    if (c.HasSolver) {
        deepest = @max(deepest, c.Solver.StackBytes);
    }
    return deepest;
}

pub fn ContractSteps(c: *Contract) i64 {
    var steps: i64 = c.Matcher.Steps;
    if (c.HasOnePass) {
        steps = cAdd(steps, c.OnePass.Steps);
    }
    if (c.HasSolver) {
        steps = cAdd(steps, c.Solver.Steps);
    }
    return steps;
}

pub fn ContractFor(re: *Regexp, maxInput: i64) Contract {
    const length: i64 = vg.cv(i64, @min(@max(maxInput, 0), subjectLimit));
    const atom: i64 = atomCost(re);
    var c: Contract = .{};
    c.MaxInput = vg.cv(i64, length);
    c.Matcher = matcherContract(re, length, atom);
    if (((re.progOK and (re.nsub > 0)) and ((re.flags & FlagNoSub) == 0))) {
        if (re.onePass) {
            c.OnePass = onePassContract(re, length, atom);
            c.HasOnePass = true;
        }
        c.Solver = solverContract(re, length, atom);
        c.HasSolver = true;
    }
    return c;
}

pub fn matcherContract(re: *Regexp, length: i64, atom: i64) BackendContract {
    var b: BackendContract = .{};
    if ((!re.progOK)) {
        b.StackBytes = matcherStackBytes;
        b.Steps = cAdd(cMul(2, length), 2);
        return b;
    }
    const n: i64 = vg.cv(i64, re.prog.ins.len);
    const k: i64 = vg.cv(i64, re.minSlots);
    var ring: i64 = vg.cv(i64, 2);
    if (re.prog.multi) {
        ring = (maxElemAhead +% 1);
    }
    const heap: i64 = workspaceHeapBound(n, k, ring);
    const weight: i64 = cAdd(cMul(4, k), 22);
    const perTest: i64 = cAdd(cAdd(atom, 2), cMul((ring -% 1), cAdd(cMul(4, k), 12)));
    var perBoundary: i64 = cMul(weight, cMul((n +% 1), (n +% 1)));
    perBoundary = cAdd(perBoundary, cMul(n, perTest));
    perBoundary = cAdd(perBoundary, cAdd(cAdd(n, cMul(2, k)), cAdd(cMul(4, ring), 38)));
    const steps: i64 = cAdd(cAdd((24 +% ring), length), cMul(cAdd(length, 1), perBoundary));
    const stack: i64 = (vg.cv(i64, matcherStackBytes) +% (equivFrames *% frameBytes));
    b.HeapBytes = heap;
    b.StackBytes = stack;
    b.Steps = steps;
    return b;
}

pub fn captureHeap(re: *Regexp, length: i64) i64 {
    const window: i64 = cAdd(cMul(4, length), cMul(8, cAdd(length, 1)));
    return cAdd((window +% 64), cMul(matchBytes, (vg.cv(i64, re.nsub) +% 1)));
}

pub fn onePassContract(re: *Regexp, length: i64, atom: i64) BackendContract {
    var b: BackendContract = .{};
    const perVisit: i64 = cAdd(atom, (vg.cv(i64, re.nsub) +% 1));
    b.HeapBytes = captureHeap(re, length);
    b.StackBytes = cMul(cAdd(astHeight(re.nodes, re.root), 4), frameBytes);
    b.Steps = cMul(cMul(astSize(re.nodes, re.root), cAdd(length, 2)), perVisit);
    return b;
}

pub fn solverContract(re: *Regexp, length: i64, atom: i64) BackendContract {
    var b: BackendContract = .{};
    const depth: i64 = solverDepth(re.nodes, re.root, length);
    const structural: i64 = @min(solverSteps(re.nodes, re.root, length), cAdd(capWorkLimit, depth));
    const tree: i64 = treeNodes(re.nodes, re.root, length);
    const perStep: i64 = cAdd(atom, cAdd(cMul(2, tree), (cMul(2, vg.cv(i64, re.minSlots)) +% 4)));
    const steps: i64 = cAdd(cMul(structural, perStep), cMul(tree, (vg.cv(i64, re.nsub) +% 2)));
    const perAlloc: i64 = cAdd(((2 *% ptreeBytes) +% mapEntryBytes), cMul(kidBytes, cAdd(solverFanout(re.nodes, re.root, length), 1)));
    var heap: i64 = cAdd(cMul(structural, perAlloc), cMul(16, vg.cv(i64, re.minSlots)));
    heap = cAdd(heap, 4096);
    heap = cAdd(heap, captureHeap(re, length));
    const stack: i64 = cMul(cAdd(depth, (equivFrames +% 4)), frameBytes);
    b.HeapBytes = heap;
    b.StackBytes = stack;
    b.Steps = steps;
    return b;
}

pub fn astSize(nodes: vg.Slice(node), ni: i32) i64 {
    var total: i64 = vg.cv(i64, 1);
    {
        var i: i64 = 0;
        while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
            total = cAdd(total, astSize(nodes, nodes.at(ni).*.ch.at(i).*));
        }
    }
    return total;
}

pub fn astHeight(nodes: vg.Slice(node), ni: i32) i64 {
    var deepest: i64 = vg.cv(i64, 0);
    {
        var i: i64 = 0;
        while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
            deepest = @max(deepest, astHeight(nodes, nodes.at(ni).*.ch.at(i).*));
        }
    }
    return (deepest +% 1);
}

pub fn atomCost(re: *Regexp) i64 {
    return atomCostNode(re.nodes, re.brackets, re.root);
}

pub fn atomCostNode(nodes: vg.Slice(node), brs: vg.Slice(bracketSet), ni: i32) i64 {
    var cost: i64 = vg.cv(i64, 1);
    switch (nodes.at(ni).*.op) {
        opChar => {
            cost = (vg.cv(i64, nodes.at(ni).*.fold.len) +% 1);
        },
        opBracket => {
            cost = bracketAtomCost(brs, nodes.at(ni).*.br);
        },
        else => {},
    }
    {
        var i: i64 = 0;
        while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
            cost = @max(cost, atomCostNode(nodes, brs, nodes.at(ni).*.ch.at(i).*));
        }
    }
    return cost;
}

pub fn bracketAtomCost(brs: vg.Slice(bracketSet), bi: i32) i64 {
    const members: i64 = (vg.cv(i64, ((brs.at(bi).*.ranges.len +% brs.at(bi).*.elems.len) +% brs.at(bi).*.equivs.len)) +% bracketFixedChecks);
    const cost: i64 = cMul((maxPreimages +% 1), members);
    if ((!bracketHasMultiMembers(brs, bi))) {
        return cost;
    }
    var elemChars: i64 = 0;
    {
        var i: i64 = 0;
        while ((i < brs.at(bi).*.elems.len)) : (i +%= 1) {
            elemChars +%= vg.cv(i64, brs.at(bi).*.elems.at(i).*.len);
        }
    }
    var multi: i64 = elemChars;
    if ((brs.at(bi).*.equivs.len > 0)) {
        var candidates: i64 = vg.cv(i64, 1);
        if (brs.at(bi).*.icase) {
            {
                var i_2: i64 = 0;
                while ((i_2 < maxElemAhead)) : (i_2 +%= 1) {
                    candidates *%= (maxPreimages +% 1);
                }
            }
        }
        multi = cAdd(multi, cMul(candidates, cMul((vg.cv(i64, brs.at(bi).*.equivs.len) +% 1), maxElemAhead)));
    }
    return cAdd(cost, cMul((maxElemAhead -% 1), multi));
}

pub fn solverSteps(nodes: vg.Slice(node), ni: i32, length: i64) i64 {
    const spans: i64 = vg.divT(cMul(cAdd(length, 1), cAdd(length, 2)), 2);
    var total: i64 = spans;
    switch (nodes.at(ni).*.op) {
        opConcat => {
            total = cAdd(total, cMul(vg.cv(i64, (nodes.at(ni).*.ch.len -% 1)), cMul(spans, cAdd(length, 2))));
        },
        opAlt => {
            total = cAdd(total, cMul(vg.cv(i64, nodes.at(ni).*.ch.len), spans));
        },
        opRepeat => {
            var states: i64 = (vg.cv(i64, nodes.at(ni).*.min) +% 1);
            if ((nodes.at(ni).*.max != infinite)) {
                states = (vg.cv(i64, nodes.at(ni).*.max) +% 1);
            }
            total = cAdd(total, cMul(cMul(2, states), cMul(spans, cAdd(length, 2))));
        },
        else => {},
    }
    {
        var i: i64 = 0;
        while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
            total = cAdd(total, solverSteps(nodes, nodes.at(ni).*.ch.at(i).*, length));
        }
    }
    return total;
}

pub fn repInstances(nodes: vg.Slice(node), ni: i32, length: i64) i64 {
    var instances: i64 = cAdd(length, (vg.cv(i64, nodes.at(ni).*.min) +% 1));
    if ((nodes.at(ni).*.max != infinite)) {
        instances = @min(instances, vg.cv(i64, nodes.at(ni).*.max));
    }
    return instances;
}

pub fn solverDepth(nodes: vg.Slice(node), ni: i32, length: i64) i64 {
    switch (nodes.at(ni).*.op) {
        opGroup, opAlt, opConcat => {
            var deepest: i64 = vg.cv(i64, 0);
            {
                var i: i64 = 0;
                while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
                    deepest = @max(deepest, solverDepth(nodes, nodes.at(ni).*.ch.at(i).*, length));
                }
            }
            if ((nodes.at(ni).*.op == opConcat)) {
                return cAdd(deepest, (vg.cv(i64, nodes.at(ni).*.ch.len) +% 1));
            }
            return (deepest +% 1);
        },
        opRepeat => {
            return cAdd((repInstances(nodes, ni, length) +% 1), solverDepth(nodes, nodes.at(ni).*.ch.at(0).*, length));
        },
        else => {},
    }
    return 1;
}

pub fn treeNodes(nodes: vg.Slice(node), ni: i32, length: i64) i64 {
    switch (nodes.at(ni).*.op) {
        opGroup, opAlt => {
            var widest: i64 = vg.cv(i64, 0);
            {
                var i: i64 = 0;
                while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
                    widest = @max(widest, treeNodes(nodes, nodes.at(ni).*.ch.at(i).*, length));
                }
            }
            return cAdd(widest, 1);
        },
        opConcat => {
            var total: i64 = vg.cv(i64, 1);
            {
                var i_2: i64 = 0;
                while ((i_2 < nodes.at(ni).*.ch.len)) : (i_2 +%= 1) {
                    total = cAdd(total, treeNodes(nodes, nodes.at(ni).*.ch.at(i_2).*, length));
                }
            }
            return total;
        },
        opRepeat => {
            return cAdd(1, cMul(repInstances(nodes, ni, length), treeNodes(nodes, nodes.at(ni).*.ch.at(0).*, length)));
        },
        else => {},
    }
    return 1;
}

pub fn solverFanout(nodes: vg.Slice(node), ni: i32, length: i64) i64 {
    var widest: i64 = vg.cv(i64, 1);
    switch (nodes.at(ni).*.op) {
        opConcat => {
            widest = vg.cv(i64, nodes.at(ni).*.ch.len);
        },
        opRepeat => {
            widest = cAdd(repInstances(nodes, ni, length), 1);
        },
        else => {},
    }
    {
        var i: i64 = 0;
        while ((i < nodes.at(ni).*.ch.len)) : (i +%= 1) {
            widest = @max(widest, solverFanout(nodes, nodes.at(ni).*.ch.at(i).*, length));
        }
    }
    return widest;
}

pub fn prepare(mem: vg.Allocator, ws: *engineWS, n: i64, k: i64, ring: i64) vg.Allocator.Error!void {
    ws.slots = try vg.make(mem, slotTable, ring);
    {
        var i: i64 = 0;
        while ((i < ring)) : (i +%= 1) {
            ws.slots.at(i).*.stamp = try vg.make(mem, u32, n);
            ws.slots.at(i).*.starts = try vg.make(mem, i32, n);
            if ((k > 0)) {
                ws.slots.at(i).*.ctr = try vg.make(mem, u32, (n *% k));
            }
        }
    }
    ws.onq = try vg.make(mem, u8, n);
    if ((k > 0)) {
        ws.bestCtr = try vg.make(mem, u32, k);
        ws.ctrBuf = try vg.make(mem, u32, k);
        ws.zeros = try vg.make(mem, u32, k);
    }
    ws.queue = try vg.makeCap(mem, u32, 0, 16);
}

pub fn workspaceHeapBound(n: i64, k: i64, ring: i64) i64 {
    var perSlot: i64 = cMul(8, n);
    if ((k > 0)) {
        perSlot = cAdd(perSlot, cMul(4, cMul(n, k)));
    }
    var heap: i64 = cAdd(cMul(ring, 104), cMul(ring, perSlot));
    heap = cAdd(heap, n);
    if ((k > 0)) {
        heap = cAdd(heap, (12 *% k));
    }
    heap = cAdd(heap, 64);
    heap = cAdd(heap, cMul(ring, cAdd(cMul(16, n), 64)));
    heap = cAdd(heap, cAdd(cMul(32, n), 272));
    return heap;
}

pub fn ctrLess(a: vg.Slice(u32), b: vg.Slice(u32)) bool {
    {
        var i: i64 = 0;
        while ((i < a.len)) : (i +%= 1) {
            if ((a.at(i).* != b.at(i).*)) {
                return (a.at(i).* < b.at(i).*);
            }
        }
    }
    return false;
}

pub fn trailingZeros64(x: u64) i64 {
    var x_v: u64 = x;
    var n: i64 = 0;
    if (((x_v & 4294967295) == 0)) {
        n +%= 32;
        x_v >>= 32;
    }
    if (((x_v & 65535) == 0)) {
        n +%= 16;
        x_v >>= 16;
    }
    if (((x_v & 255) == 0)) {
        n +%= 8;
        x_v >>= 8;
    }
    if (((x_v & 15) == 0)) {
        n +%= 4;
        x_v >>= 4;
    }
    if (((x_v & 3) == 0)) {
        n +%= 2;
        x_v >>= 2;
    }
    if (((x_v & 1) == 0)) {
        n +%= 1;
    }
    return n;
}

pub fn runPhaseA(mem: vg.Allocator, re: *Regexp, subject: vg.Str, eflags: u32) vg.Allocator.Error!engineResult {
    var ws: engineWS = .{};
    var e: phaseAState = .{};
    e.subject = subject;
    e.eflags = eflags;
    e.k = re.minSlots;
    e.ring = 2;
    e.nlMode = ((re.flags & FlagNewline) != 0);
    if (re.prog.multi) {
        e.ring = (maxElemAhead +% 1);
    }
    try prepare(mem, &ws, re.prog.ins.len, e.k, e.ring);
    try paRun(mem, &e, &ws, re);
    var result: engineResult = .{};
