    const ok: bool = _t1[1];
    return ok;
}

pub fn LocaleCollatingPrefix(l: *Locale, seq: vg.Slice(i32)) i64 {
    if (((!l.valid) or (seq.len == 0))) {
        return 0;
    }
    const maximum: i64 = @min(seq.len, l.maxSeq);
    {
        var candidate: i64 = maximum;
        while ((candidate >= 2)) : (candidate -%= 1) {
            if (localeIsCollatingElement(l, seq.sub(0, candidate))) {
                return candidate;
            }
        }
    }
    if (localeIsCollatingElement(l, seq.sub(0, 1))) {
        return 1;
    }
    return 0;
}

pub fn findPair(l: *Locale, sec: i64, first: i64, count: i64, element: u32) Tup_u32_bool {
    var low: i64 = first;
    var high: i64 = (first +% count);
    while ((low < high)) {
        const middle: i64 = (low +% vg.divT((high -% low), 2));
        const key: u32 = u32At(l, sec, (2 *% middle));
        if ((key == element)) {
            return .{ u32At(l, sec, ((2 *% middle) +% 1)), true };
        }
        if ((key > element)) {
            high = middle;
        } else {
            low = (middle +% 1);
        }
    }
    return .{ 0, false };
}

pub fn primaryToken(l: *Locale, element: u32) u64 {
    const row: CollProfile = collationProfileRow(l, vg.cv(i64, l.collationProfile));
    const _t1 = findPair(l, secCollationOverrides, row.OverrideFirst, row.OverrideCount, element);
    var rep: u32 = _t1[0];
    var ok: bool = _t1[1];
    if (ok) {
