    }
    const rootCount: i64 = vg.divT(sectionLen(l, secRootEquivalences), 8);
    {
        const _t2 = findPair(l, secRootEquivalences, 0, rootCount, element);
        rep = _t2[0];
        ok = _t2[1];
    }
    if (ok) {
        return (4294967296 | vg.cv(u64, rep));
    }
    return vg.cv(u64, element);
}

pub fn localePrimaryEqual(l: *Locale, left: vg.Slice(i32), right: vg.Slice(i32)) bool {
    if ((!l.valid)) {
        return false;
