    }
    return (primaryToken(l, leftElement) == primaryToken(l, rightElement));
}

pub fn localeMinEquivLength(l: *Locale, seq: vg.Slice(i32)) i64 {
    if ((!l.valid)) {
        return seq.len;
    }
    const _t1 = collatingElementID(l, seq);
    const element: u32 = _t1[0];
    const ok: bool = _t1[1];
    if ((!ok)) {
        return seq.len;
    }
    if ((element < firstSequenceID)) {
        return 1;
    }
    if (l.posix) {
        return seq.len;
    }
    const token: u64 = primaryToken(l, element);
    var best: i64 = seq.len;
    const row: CollProfile = collationProfileRow(l, vg.cv(i64, l.collationProfile));
    best = minTokenLength(l, secCollationOverrides, row.OverrideFirst, row.OverrideCount, token, best);
    if ((best == 1)) {
        return 1;
    }
    const rootCount: i64 = vg.divT(sectionLen(l, secRootEquivalences), 8);
    return minTokenLength(l, secRootEquivalences, 0, rootCount, token, best);
}

pub fn minTokenLength(l: *Locale, sec: i64, first: i64, count: i64, token: u64, best: i64) i64 {
    var best_v: i64 = best;
    {
        var i: i64 = first;
        while ((i < (first +% count))) : (i +%= 1) {
            const candidate: u32 = u32At(l, sec, (2 *% i));
            if ((primaryToken(l, candidate) != token)) {
                continue;
            }
            if ((candidate < firstSequenceID)) {
                return 1;
            }
            if ((!isContraction(l, candidate))) {
                continue;
            }
            const index: i64 = vg.cv(i64, (candidate -% firstSequenceID));
            best_v = @min(best_v, vg.cv(i64, u32At(l, secSequences, ((2 *% index) +% 1))));
        }
    }
    return best_v;
}

pub fn localeSupportsRanges(l: *Locale) bool {
