        d.runes = try vg.append(mem, i32, d.runes, r);
        i +%= size;
    }
    d.byteAt = try vg.append(mem, i64, d.byteAt, eo);
    return d;
}

pub fn indexOfByte(s: vg.Str, c: u8) i64 {
