                    if (((nodes.at(a).*.minL <= nodes.at(b).*.maxL) and (nodes.at(b).*.minL <= nodes.at(a).*.maxL))) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

pub fn firstSet(mem: vg.Allocator, nodes: vg.Slice(node), ni: i32) vg.Allocator.Error!Tup_si32_bool {
