            return .{ out_2, true };
        },
        opConcat => {
            var out_3: vg.Slice(i32) = .{};
            {
                var i_2: i64 = 0;
                while ((i_2 < nodes.at(ni).*.ch.len)) : (i_2 +%= 1) {
                    const child: i32 = nodes.at(ni).*.ch.at(i_2).*;
                    const _t2 = try firstSet(mem, nodes, child);
                    const sub_2: vg.Slice(i32) = _t2[0];
                    const ok_2: bool = _t2[1];
