pub fn disjointFirsts(mem: vg.Allocator, nodes: vg.Slice(node), ni: i32) vg.Allocator.Error!bool {
    const count: i64 = nodes.at(ni).*.ch.len;
    const firsts: vg.Slice(vg.Slice(i32)) = try vg.make(mem, vg.Slice(i32), count);
    var nullable: i64 = 0;
    {
        var i: i64 = 0;
        while ((i < count)) : (i +%= 1) {
            const branch: i32 = nodes.at(ni).*.ch.at(i).*;
            const _t1 = try firstSet(mem, nodes, branch);
            const set: vg.Slice(i32) = _t1[0];
            const ok: bool = _t1[1];
            if ((!ok)) {
                return false;
            }
            if ((nodes.at(branch).*.minL == 0)) {
                nullable +%= 1;
            }
            firsts.at(i).* = set;
        }
    }
    if ((nullable > 1)) {
        return false;
    }
    {
        var i_2: i64 = 0;
        while ((i_2 < count)) : (i_2 +%= 1) {
            {
                var k: i64 = (i_2 +% 1);
                while ((k < count)) : (k +%= 1) {
                    {
                        var m: i64 = 0;
                        while ((m < firsts.at(i_2).*.len)) : (m +%= 1) {
                            if (runesContain(firsts.at(k).*, firsts.at(i_2).*.at(m).*)) {
                                return false;
                            }
                        }
                    }
                }
            }
        }
    }
    nodes.at(ni).*.firsts = firsts;
    return true;
}

pub fn onePassCaps(re: *Regexp, d: *decoded, ni: i32, i: i64, j: i64, eflags: u32, caps: vg.Slice(Match)) bool {
    const span: i64 = (j -% i);
    if (((span < re.nodes.at(ni).*.minL) or (span > re.nodes.at(ni).*.maxL))) {
        return false;
    }
    switch (re.nodes.at(ni).*.op) {
        opChar => {
            return charMatches(re, ni, d.runes.at(i).*);
        },
        opAny => {
            return anyMatches(re, d.runes.at(i).*);
        },
        opBracket => {
            return bracketMatchesOne(re.brackets, re.nodes.at(ni).*.br, &re.loc, d.runes.at(i).*);
        },
        opBOL => {
            return atBOL(re, d, i, eflags);
        },
        opEOL => {
            return atEOL(re, d, i, eflags);
        },
        opGroup => {
            const gi: i64 = re.nodes.at(ni).*.index;
            {
                var k: i64 = 0;
                while ((k < re.nested.at(gi).*.len)) : (k +%= 1) {
                    setMatch(caps, vg.cv(i64, re.nested.at(gi).*.at(k).*), (-%1), (-%1));
                }
            }
            setMatch(caps, gi, i, j);
            return onePassCaps(re, d, re.nodes.at(ni).*.ch.at(0).*, i, j, eflags, caps);
        },
        opConcat => {
            var rest: i64 = span;
            {
                var k_2: i64 = 0;
                while ((k_2 < re.nodes.at(ni).*.ch.len)) : (k_2 +%= 1) {
                    rest -%= re.nodes.at(re.nodes.at(ni).*.ch.at(k_2).*).*.minL;
                }
            }
            var at: i64 = i;
            {
                var k_3: i64 = 0;
                while ((k_3 < re.nodes.at(ni).*.ch.len)) : (k_3 +%= 1) {
                    const child: i32 = re.nodes.at(ni).*.ch.at(k_3).*;
                    var length: i64 = re.nodes.at(child).*.minL;
                    if ((!fixedLength(re.nodes, child))) {
                        length +%= rest;
                    }
                    if (((length < 0) or (!onePassCaps(re, d, child, at, (at +% length), eflags, caps)))) {
                        return false;
                    }
                    at +%= length;
                }
            }
            return (at == j);
        },
        opRepeat => {
            if ((span == 0)) {
                return true;
            }
            const child_2: i32 = re.nodes.at(ni).*.ch.at(0).*;
            const size: i64 = re.nodes.at(child_2).*.minL;
            const count: i64 = vg.divT(span, size);
            if ((((vg.remT(span, size) != 0) or (count < re.nodes.at(ni).*.min)) or ((re.nodes.at(ni).*.max != infinite) and (count > re.nodes.at(ni).*.max)))) {
                return false;
            }
            var at_2: i64 = i;
            {
                var k_4: i64 = 0;
                while ((k_4 < count)) : (k_4 +%= 1) {
                    if ((!onePassCaps(re, d, child_2, at_2, (at_2 +% size), eflags, caps))) {
                        return false;
                    }
                    at_2 +%= size;
                }
            }
            return true;
        },
        opAlt => {
            var chosen: i64 = (-%1);
            {
                var idx: i64 = 0;
                while ((idx < re.nodes.at(ni).*.ch.len)) : (idx +%= 1) {
                    const branch: i32 = re.nodes.at(ni).*.ch.at(idx).*;
                    if (((span < re.nodes.at(branch).*.minL) or (span > re.nodes.at(branch).*.maxL))) {
                        continue;
                    }
                    if ((chosen >= 0)) {
                        chosen = (-%1);
                        break;
                    }
                    chosen = idx;
                }
            }
            if (((chosen < 0) and (re.nodes.at(ni).*.firsts.p != null))) {
                if ((span == 0)) {
                    {
                        var idx_2: i64 = 0;
                        while ((idx_2 < re.nodes.at(ni).*.ch.len)) : (idx_2 +%= 1) {
                            if ((re.nodes.at(re.nodes.at(ni).*.ch.at(idx_2).*).*.minL == 0)) {
                                chosen = idx_2;
                                break;
                            }
                        }
                    }
                } else {
                    {
                        var idx_3: i64 = 0;
                        while ((idx_3 < re.nodes.at(ni).*.ch.len)) : (idx_3 +%= 1) {
                            if (runesContain(re.nodes.at(ni).*.firsts.at(idx_3).*, d.runes.at(i).*)) {
                                chosen = idx_3;
                                break;
                            }
                        }
                    }
                }
            }
            if ((chosen < 0)) {
                return false;
            }
            return onePassCaps(re, d, re.nodes.at(ni).*.ch.at(chosen).*, i, j, eflags, caps);
        },
        else => {},
    }
    return false;
}

pub fn buildScanFilter(mem: vg.Allocator, pr: *program, newlineMode: bool) vg.Allocator.Error!void {
    var ok: bool = true;
