    const seen: vg.Slice(bool) = try vg.make(mem, bool, pr.ins.len);
    var stack: vg.Slice(u32) = try vg.makeCap(mem, u32, 0, 16);
    stack = try vg.append(mem, u32, stack, pr.start);
    while ((stack.len > 0)) {
